/**
 * By default renders no output
 * @return string
 * @since 6.0.0
 */
public function render() {
	return '';
}

public function manageOCMRequests(string $ocmPath): Response {
	if (!mb_check_encoding($ocmPath, 'UTF-8')) {
		throw new OCMArgumentException('path is not UTF-8');
	}

	$ocmAddress = null;
	$params = $this->request->getParams();
	foreach (['owner', 'sender', 'sharedBy'] as $field) {
		if (is_string($params[$field] ?? null) && $params[$field] !== '') {
			$ocmAddress = $params[$field];
			break;
		}
	}

	try {
		$signedRequest = $this->ocmDiscoveryService->getIncomingSignedRequest($ocmAddress);
	} catch (IncomingRequestException $e) {
		$this->logger->warning('incoming ocm request exception', ['exception' => $e]);
		$response = new JSONResponse(['message' => $e->getMessage(), 'validationErrors' => []], Http::STATUS_BAD_REQUEST);
		$response->throttle();
		return $response;
	}

	// assuming that ocm request contains a json array
	$payload = $signedRequest?->getBody() ?? file_get_contents('php://input');
	try {
		$payload = ($payload) ? json_decode($payload, true, 512, JSON_THROW_ON_ERROR) : null;
	} catch (JsonException $e) {
		$this->logger->debug('json decode error', ['exception' => $e]);
		$payload = null;
	}

	$event = new OCMEndpointRequestEvent(
		$this->request->getMethod(),
		preg_replace('@/+@', '/', $ocmPath),
		$payload,
		$signedRequest?->getOrigin()
	);
	$this->eventDispatcher->dispatchTyped($event);

	return $event->getResponse() ?? new Response(Http::STATUS_NOT_FOUND);
}

public function exec() {
	/** @var IEventLogger $eventLogger */
	$eventLogger = \OCP\Server::get(IEventLogger::class);
	$eventLogger->start('dav_server_exec', '');
	$this->server->start();
	$eventLogger->end('dav_server_exec');
	if ($this->profiler->isEnabled()) {
		$eventLogger->end('runtime');
		$profile = $this->profiler->collect(\OCP\Server::get(IRequest::class), new Response());
		$this->profiler->saveProfile($profile);
	}
}

public function cropImagePreviews(bool $value): Response {
	$this->config->setUserValue($this->userSession->getUser()->getUID(), 'files', 'crop_image_previews', $value ? '1' : '0');
	return new Response();
}

public function showGridView(bool $show): Response {
	$this->config->setUserValue($this->userSession->getUser()->getUID(), 'files', 'show_grid', $show ? '1' : '0');
	return new Response();
}

public function showHiddenFiles(bool $value): Response {
	$this->config->setUserValue($this->userSession->getUser()->getUID(), 'files', 'show_hidden', $value ? '1' : '0');
	return new Response();
}

public function testCropImagePreviews(): void {
	$crop = true;

	$this->config->expects($this->once())
		->method('setUserValue')
		->with($this->user->getUID(), 'files', 'crop_image_previews', '1');

	$expected = new Response();
	$actual = $this->apiController->cropImagePreviews($crop);

	$this->assertEquals($expected, $actual);
}

public function edit(string $token): Response {
	$this->eventDispatcher->dispatchTyped(new RegisterDirectEditorEvent($this->directEditingManager));
	try {
		return $this->directEditingManager->edit($token);
	} catch (Exception $e) {
		$this->logger->error($e->getMessage(), ['exception' => $e]);
		return new NotFoundResponse();
	}
}

/**
 * @template-covariant S of Http::STATUS_*
 * @template-covariant T of mixed
 * @template-covariant H of array<string, mixed>
 * @template-extends Response<Http::STATUS_*, array<string, mixed>>
 */
abstract class BaseResponse extends Response {
	/** @var array */
	protected $data;

	/**
	 * BaseResponse constructor.
	 *
	 * @param DataResponse<S, T, H> $dataResponse
	 */
	public function __construct(
		DataResponse $dataResponse,
		protected string $format = 'xml',
		protected ?string $statusMessage = null,
		protected ?int $itemsCount = null,
		protected ?int $itemsPerPage = null,
	) {
		parent::__construct();

		$this->data = $dataResponse->getData();

		$this->setHeaders($dataResponse->getHeaders());
		$this->setStatus($dataResponse->getStatus());
		$this->setETag($dataResponse->getETag());
		$this->setLastModified($dataResponse->getLastModified());
		$this->setCookies($dataResponse->getCookies());

		if ($dataResponse->isThrottled()) {
			$throttleMetadata = $dataResponse->getThrottleMetadata();
			$this->throttle($throttleMetadata);
		}

		if ($this->format === 'json') {
			$this->addHeader(
				'Content-Type', 'application/json; charset=utf-8'
			);
		} else {
			$this->addHeader(
				'Content-Type', 'application/xml; charset=utf-8'
			);
		}
	}

	/**
	 * @param array<string,string|int> $meta
	 * @return string
	 */
	protected function renderResult(array $meta): string {
		$status = $this->getStatus();
		if ($status === Http::STATUS_NO_CONTENT
			|| $status === Http::STATUS_NOT_MODIFIED
			|| ($status >= 100 && $status <= 199)) {
			// Those status codes are not supposed to have a body:
			// https://stackoverflow.com/q/8628725
			return '';
		}

		$response = [
			'ocs' => [
				'meta' => $meta,
				'data' => $this->data,
			],
		];

		if ($this->format === 'json') {
			return $this->toJson($response);
		}

		$writer = new \XMLWriter();
		$writer->openMemory();
		$writer->setIndent(true);
		$writer->startDocument();
		$this->toXML($response, $writer);
		$writer->endDocument();
		return $writer->outputMemory(true);
	}

	/**
	 * @psalm-taint-escape has_quotes
	 * @psalm-taint-escape html
	 */
	protected function toJson(array $array): string {
		return \json_encode($array, \JSON_HEX_TAG);
	}

	protected function toXML(array $array, \XMLWriter $writer): void {
		foreach ($array as $k => $v) {
			if ($k === '@attributes' && is_array($v)) {
				foreach ($v as $k2 => $v2) {
					$writer->writeAttribute($k2, $v2);
				}
				continue;
			}

			if (\is_string($k) && str_starts_with($k, '@')) {
				$writer->writeAttribute(substr($k, 1), $v);
				continue;
			}

			if (\is_numeric($k)) {
				$k = 'element';
			}

			if ($v instanceof \stdClass) {
				$v = [];
			}

			if ($k === '$comment') {
				$writer->writeComment($v);
			} elseif (\is_array($v)) {
				$writer->startElement($k);
				$this->toXML($v, $writer);
				$writer->endElement();
			} elseif ($v instanceof \JsonSerializable) {
				$writer->startElement($k);
				$this->toXML($v->jsonSerialize(), $writer);
				$writer->endElement();
			} elseif ($v === null) {
				$writer->writeElement($k);
			} else {
				$writer->writeElement($k, (string)$v);
			}
		}
	}

	public function getOCSStatus() {
		return parent::getStatus();
	}
}

public function testApp(): void {
	self::invokePrivate($this->container, 'appName', ['bar']);
	$this->container->setInInternalContainer('OCA\Bar\Controller\Foo', $this->controller);
	$this->container->registerParameter('urlParams', ['_route' => 'not-profiler']);

	$return = ['HTTP/2.0 200 OK', [], [], null, new Response()];
	$this->dispatcher->expects($this->once())
		->method('dispatch')
		->with($this->equalTo($this->controller),
			$this->equalTo($this->controllerMethod))
		->willReturn($return);

	$this->io->expects($this->never())
		->method('setOutput');

	App::main('Foo', $this->controllerMethod, $this->container);
}

public function testControllerNameAndMethodAreBeingPassed(): void {
	$return = ['HTTP/2.0 200 OK', [], [], null, new Response()];
	$this->dispatcher->expects($this->once())
		->method('dispatch')
		->with($this->equalTo($this->controller),
			$this->equalTo($this->controllerMethod))
		->willReturn($return);

	$this->io->expects($this->never())
		->method('setOutput');

	App::main($this->controllerName, $this->controllerMethod,
		$this->container);
}

class Response implements IResponse {
	public function __construct(
		private ResponseInterface $response,
		private bool $stream = false,
	) {
	}

	#[\Override]
	public function getBody() {
		return $this->stream
			? $this->response->getBody()->detach()
			:$this->response->getBody()->getContents();
	}

	#[\Override]
	public function getStatusCode(): int {
		return $this->response->getStatusCode();
	}

	#[\Override]
	public function getHeader(string $key): string {
		$headers = $this->response->getHeader($key);

		if (count($headers) === 0) {
			return '';
		}

		return $headers[0];
	}

	#[\Override]
	public function getHeaders(): array {
		return $this->response->getHeaders();
	}
}

/**
 * Class DataDisplayResponse
 *
 * @since 8.1.0
 * @template-covariant S of Http::STATUS_*
 * @template-covariant H of array<string, mixed>
 * @template-extends Response<Http::STATUS_*, array<string, mixed>>
 */
class DataDisplayResponse extends Response {
	/**
	 * response data
	 * @var string
	 */
	protected $data;

	/**
	 * @param string $data the data to display
	 * @param S $statusCode the Http status code, defaults to 200
	 * @param H $headers additional key value based headers
	 * @since 8.1.0
	 */
	public function __construct(string $data = '', int $statusCode = Http::STATUS_OK, array $headers = []) {
		parent::__construct($statusCode, $headers);

		$this->data = $data;
		$this->addHeader('Content-Disposition', 'inline; filename=""');
	}

	/**
	 * Outputs data. No processing is done.
	 * @return string
	 * @since 8.1.0
	 */
	#[\Override]
	public function render() {
		return $this->data;
	}

	/**
	 * Sets values in the data
	 * @param string $data the data to display
	 * @return DataDisplayResponse Reference to this object
	 * @since 8.1.0
	 */
	public function setData($data) {
		$this->data = $data;

		return $this;
	}

	/**
	 * Used to get the set parameters
	 * @return string the data
	 * @since 8.1.0
	 */
	public function getData() {
		return $this->data;
	}
}

